INSERT INTO LabFlag (id, labId, title, description, points, answerHash, answerHint, createdAt, updatedAt) VALUES ('37d96053-4049-43e8-89ba-046fef664892', '88de7b45-d1c8-4d13-97df-66805199f591', 'Schema Inspector', 'Run: psql shopdb -c SELECT table_name FROM information_schema.tables WHERE table_schema = public. How many tables are listed?', 75, '$2b$10$hPvrlw5hko8CljjjfPFtzexHQ1VyjS/QQsnLoRR3T9cGsayPhCdTy', NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO LabFlag (id, labId, title, description, points, answerHash, answerHint, createdAt, updatedAt) VALUES ('c7ce3bd5-7714-4ab3-b741-a3e7ec95681d', '88de7b45-d1c8-4d13-97df-66805199f591', 'Permission Auditor', 'Run: psql shopdb -c SELECT has_table_privilege. Syntax: psql shopdb -c SELECT has_table_privilege. What does the function return for a valid user with SELECT on products table?', 75, '$2b$10$1Jyb0AK/OvHp288uuM1eAuWSQI6LwRDQZmcP.0mGEGW1jGVzM0ZV2', NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO LabFlag (id, labId, title, description, points, answerHash, answerHint, createdAt, updatedAt) VALUES ('5bacec85-4e16-4951-ab12-759f5c1423d2', '88de7b45-d1c8-4d13-97df-66805199f591', 'Data Updater', 'Run: psql shopdb -c UPDATE products SET price=price*1.1 WHERE name LIKE Mouse. Then run: psql shopdb -c SELECT price FROM products WHERE name LIKE Mouse. What is the new price rounded to 2 decimals?', 100, '$2b$10$tQTtvtYh5oGY69oTwT5ke.q0c5lc.mIxImWBdnU9YTe79Y7BMofJG', NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO LabFlag (id, labId, title, description, points, answerHash, answerHint, createdAt, updatedAt) VALUES ('e720dc3d-cb7e-40dc-98dd-f276e9925bc6', '88de7b45-d1c8-4d13-97df-66805199f591', 'Serial Expert', 'Insert 3 more products using INSERT INTO products. Then run: psql shopdb -c SELECT MAX(id) FROM products. What is the highest id?', 100, '$2b$10$SN3TIKYZr7WP4mWZ.GTSyujy1uWcI74eYfa7gBK7V9WiQCMZAKlaK', NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
